parameters.jsCode:
// Two outputs from one node: `report` is what gets recorded and returned, `queue` is what the send
// limb consumes. They are separate because `queue` carries an api_key per row and `report` must
// never contain one (the provisioning workflows' invariant 7, same rule).
const base = $('Resolve Campaigns').first().json;
const rows = $input.all().map((i) => i.json ?? {}).filter((r) => r.lead_id);
const byClient = new Map(base.resolved.map((r) => [r.client_id, r]));

const queue = rows.map((r) => {
  const c = byClient.get(r.client_id);
  return {
    client: c?.client_name ?? r.client_id,
    campaign_id: c?.campaign_id ?? null,
    api_key: c?.api_key ?? null,
    lead_id: r.lead_id,
    profile_url: r.linkedin_url,
  };
}).filter((q) => q.campaign_id && q.api_key);

const per_client = {};
for (const q of queue) per_client[q.client] = (per_client[q.client] ?? 0) + 1;

return [{ json: {
  window: { since: base.since, until: base.until },
  dry_run: base.dry_run,
  clients_seen: base.clients_seen,
  clients_resolved: base.resolved.length,
  blocked: base.blocked,
  would_send: queue.length,
  per_client,
  sample: queue.slice(0, 20).map(({ client, lead_id, profile_url }) => ({ client, lead_id, profile_url })),
  queue,
} }];

// n8n preserves item order, so the i-th response belongs to the i-th queued lead.
const describe = (v) => {
  if (v == null) return null;
  if (typeof v === 'string') return v;
  return v.message ?? v.description ?? (() => { try { return JSON.stringify(v); } catch (e) { return String(v); } })();
};
const planned = $('Plan Imports').all().map((i) => i.json);
const results = $input.all().map((i) => i.json ?? {});
const sent_lead_ids = [];
const failed = [];
planned.forEach((p, i) => {
  const r = results[i] ?? {};
  // statusCode ONLY. Aimfox answers success with status:"ok", and Number('ok') is NaN — reading the
  // vendor's `status` as an HTTP code scores a failure as a success.
  const code = Number(r.statusCode ?? 0);
  if (Boolean(r.error) || code >= 400) failed.push(`${p.client}/${p.lead_id} — ${describe(r.message ?? r.error) ?? 'HTTP ' + code}`);
  else sent_lead_ids.push(p.lead_id);
});
return [{ json: { sent_lead_ids, failed } }];

const describe = (v) => {
  if (v == null) return null;
  if (typeof v === 'string') return v;
  return v.message ?? v.description ?? (() => { try { return JSON.stringify(v); } catch (e) { return String(v); } })();
};
const plan = $('Merge Outcome').first().json;
const rec = $json ?? {};
const failed = Boolean(rec.error);
return [{ json: { ...plan, recorded: !failed,
  ...(failed ? { record_error: describe(rec.message ?? rec.error) } : {}) } }];

// Three entry points, one shape. Without this, every `$json` read below depends on which trigger
// fired — the same trap the setup workflows' Input node exists to close.
const fromWebhook = $('Webhook').isExecuted;
const fromSchedule = $('Schedule').isExecuted;
const raw = fromWebhook ? ($('Webhook').first().json?.body ?? {}) : ($json ?? {});

// One window, computed once, so every query and the audit row agree. Yesterday in UTC, matching
// branch L's intent — it compares a sheet cell against `$now.minus({days:1})`. Widening this to the
// whole backlog is a business decision, not a port: that backlog is at least ~670 people spread over
// eight months, measured on a mirror that knows 3 of the 9 Aimfox clients — production is
// more. Each row is a LinkedIn connection request to one of them.
const end = new Date(Date.UTC(new Date().getUTCFullYear(), new Date().getUTCMonth(), new Date().getUTCDate()));
const start = new Date(end.getTime() - 24 * 60 * 60 * 1000);

// Only the schedule may send. The webhook is UNAUTHENTICATED, so honouring `dry_run: false` in its
// body would let anyone who learns the path queue LinkedIn invites into a client's campaign — a far
// worse hole than the provisioning webhooks, whose worst case is an idempotent, additive no-op.
// Refusing it here is structural: there is no request body that makes a webhook call send.
// A `Start` call is n8n-authenticated, so it may opt in explicitly.
const dry_run = fromSchedule ? false
  : fromWebhook ? true
  : raw.dry_run === false ? false
  : true;

return [{ json: {
  client_id: raw.client_id ?? '',
  since: raw.since ?? start.toISOString(),
  until: raw.until ?? end.toISOString(),
  dry_run,
  via: fromWebhook ? 'webhook' : fromSchedule ? 'schedule' : 'manual',
} }];

parameters.query:
-- Through the RPC, not raw SQL: ADR-0015 keeps `leads` RPC-owned and pnpm n8n:validate refuses the
-- direct UPDATE. The function is idempotent — an already-stamped lead keeps its first timestamp —
-- and an empty array stamps nothing, which is why this needs no branch around it.
select public.mark_linkedin_invited(
  (select coalesce(array_agg(x::uuid), '{}'::uuid[])
     from jsonb_array_elements_text($1::jsonb) as t(x))
) as stamped;

parameters.jsCode:
// One shape for Mark Invited, Record Run and the response, whether or not anything was sent.
// `queue` is dropped here: it carries an api_key per row and everything downstream is recorded.
const plan = $('Build Plan').first().json;
const { queue, ...report } = plan;
const c = $('Collect Imports').isExecuted ? ($('Collect Imports').first().json ?? {}) : { sent_lead_ids: [], failed: [] };
return [{ json: {
  ...report,
  mode: plan.dry_run === false ? 'live' : 'shadow',
  sent: (c.sent_lead_ids ?? []).length,
  failed: c.failed ?? [],
  sent_lead_ids: c.sent_lead_ids ?? [],
} }];

// One item per lead. An empty array means Add To Audience does not execute at all — the same
// structural dry-run safety the provisioning workflows use, not a flag inside the HTTP node.
const p = $json;
if (p.dry_run !== false) return [];
return (p.queue ?? []).map((q) => ({ json: q }));

// Collapses N per-client responses into ONE item, so every node downstream runs exactly once.
// n8n preserves item order, so the i-th response belongs to the i-th client.
const clients = $('Read Clients').all().map((i) => i.json);
const responses = $input.all().map((i) => i.json ?? {});

// Matched by name across the WHOLE list. Branch L reads campaigns[0] and nothing else, which is
// why it imported for 0 of 9 clients on 2026-08-09 (defect 1).
const resolved = [];
const blocked = [];
clients.forEach((c, i) => {
  const raw = responses[i] ?? {};
  if (raw.error || raw.status === 'fail') {
    blocked.push({ client: c.client_name, reason: 'vendor call failed' });
    return;
  }
  const all = raw.campaigns ?? [];
  const found = all.find((x) => String(x?.name ?? '') === 'AutoConnect');
  if (!found) { blocked.push({ client: c.client_name, reason: 'no AutoConnect campaign' }); return; }
  if (found.state !== 'ACTIVE') { blocked.push({ client: c.client_name, reason: `AutoConnect is ${found.state}` }); return; }
  resolved.push({ client_id: c.client_id, client_name: c.client_name, campaign_id: found.id, api_key: c.api_key });
});

return [{ json: {
  ...$('Input').first().json,
  clients_seen: clients.length,
  resolved,
  blocked,
} }];
